{
  "summary": "Calculer les tonnes-kilomètres à partir des données du relevé d’expéditions en utilisant les unités fournies et en respectant les contraintes de conversion.",
  "actions": [
    {
      "tool": "construct_table",
      "name": "table.json",
      "schema": {
        "expeditions": {
          "charge": "INTEGER",
          "lot": "TEXT",
          "trajet": "INTEGER",
          "u_charge": "TEXT",
          "u_trajet": "TEXT"
        }
      },
      "sql": "SELECT charge, trajet, u_charge, u_trajet FROM expeditions"
    },
    {
      "tool": "run_table",
      "name": "table.json",
      "input": {
        "dataset": "releve-transport-27"
      }
    },
    {
      "tool": "read_artifact",
      "name": "calc.json"
    },
    {
      "tool": "write_document",
      "name": "result.md",
      "content": "Calcul des tonnes-kilomètres à partir des données du relevé d’expéditions. Les unités kg et t sont converties en tonnes, et les unités m et km sont converties en kilomètres. Le calcul est effectué en multipliant la charge (en tonnes) par le trajet (en kilomètres) pour chaque ligne, puis en sommant les résultats."
    },
    {
      "tool": "construct_table",
      "name": "table_tonnes_km.json",
      "schema": {
        "expeditions": {
          "tonnes_km": "TEXT"
        }
      },
      "sql": "SELECT (CASE WHEN u_charge = 'kg' THEN charge / 1000 ELSE charge END) * (CASE WHEN u_trajet = 'm' THEN trajet / 1000 ELSE trajet END) AS tonnes_km FROM expeditions"
    },
    {
      "tool": "run_table",
      "name": "table_tonnes_km.json",
      "input": {
        "dataset": "releve-transport-27"
      }
    },
    {
      "tool": "read_artifact",
      "name": "table_tonnes_km.json"
    },
